import { test, expect } from '@playwright/test';

test.describe('Skip to content link accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com');
  });

  test('should be visible on the page', async ({ page }) => {
    const skipLink = page.getByText('Skip to content');
    await expect(skipLink).toBeVisible();
  });

  test('should navigate to main content when clicked', async ({ page }) => {
    const skipLink = page.getByText('Skip to content');
    await skipLink.click();
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(page.url()).toBe('https://yourwebsite.com#main-content'); // Adjust the URL as necessary
  });
});
